// Math Sounds
// Defines the 10 mathematical curves, waveforms, coordinate ranges, and timing.

#define PI 3.141592653589793
#define SEG_DURATION 5.0
#define TOTAL_DURATION 50.0

// Coordinate axis bounds: vec2(min, max)
#define X_RANGE vec2(-8.5, 8.5)
#define Y_RANGE vec2(-3.5, 3.5)

// Repeat a segment or -1 to cycle all of them
#define SEG -1

// --- Base Waveform Oscillators ---

// Triangle wave: period 1.0, range [-1, 1]
float tri(float u) {
    return 2.0 * abs(2.0 * fract(u) - 1.0) - 1.0;
}

// Sawtooth wave: period 1.0, range [-1, 1]
float saw(float u) {
    return 2.0 * fract(u) - 1.0;
}

// Square wave: period 1.0, range [-1, 1]
float sqr(float u) {
    return fract(u) < 0.5 ? 1.0 : -1.0;
}

// --- Reusable Sound Texture Building Blocks (Pure Phase Driven) ---

// 1. Pure Sine wave
float soundSine(float phase) {
    return sin(2.0 * PI * phase);
}

// 2. Triangle wave
float soundTri(float phase) {
    return tri(phase);
}

// 3. Sawtooth wave
float soundSaw(float phase) {
    return saw(phase);
}

// 4. Square wave
float soundSquare(float phase) {
    return sqr(phase);
}

// 5. Frequency Modulation (FM)
float soundFM(float carrierPhase, float modPhase, float modIndex) {
    float modulator = sin(2.0 * PI * modPhase) * modIndex;
    return sin(2.0 * PI * carrierPhase + modulator);
}

// 6. Arpeggiated decaying note pulse
float soundArp(float phase, float stepVal, float decayRate) {
    float env = exp(-decayRate * fract(stepVal));
    return sin(2.0 * PI * phase) * env;
}

// 7. Percussive drum kick / transient burst
float soundDrum(float phase, float stepVal, float decayRate) {
    float env = exp(-decayRate * fract(stepVal));
    return sin(2.0 * PI * phase * (1.0 + 2.5 * env)) * env;
}

// 8. Additive harmonic richness (fundamental + 2nd + 3rd harmonics)
float soundHarmonics(float phase) {
    return 0.60 * sin(2.0 * PI * phase) +
           0.28 * sin(4.0 * PI * phase) +
           0.12 * sin(6.0 * PI * phase);
}

// Evaluates the mathematical function y = f(x) for segment 0..9
float evalMathCurve(int seg, float x) {
    if (seg == 0) {
        // Formula 1: Symmetrical Sawtooth with exponential decay towards +/- edges
        float sw = 1.0 - 2.0 * fract(abs(x));
        return 2.6 * sw * exp(-0.15 * abs(x));
    } else if (seg == 1) {
        // Formula 2: Stepped staircase quantizer (micro-smoothed edges eliminate clicks)
        float val = 7.2 - 0.85 * abs(x);
        float base = floor(val);
        float frac = val - base;
        float tStep = clamp(frac / 0.04, 0.0, 1.0);
        float stepVal = base + tStep * tStep * (3.0 - 2.0 * tStep);
        return 0.52 * stepVal - 1.65;
    } else if (seg == 2) {
        // Formula 3: Piecewise sinusoidal FM chirp
        float m4 = mod(x, 4.0);
        float m2 = mod(x, 2.0);
        if (m4 < 2.0) {
            return 2.2 * sin(6.0 * PI * m2) * (1.0 - 0.3 * m2);
        } else {
            return 2.5 * sin(16.0 * PI * fract(x)) * exp(-0.8 * m2);
        }
    } else if (seg == 3) {
        // Formula 4: Staircase pitch arpeggiator
        if (fract(4.0 * x) < 0.65) {
            float s1 = mod(floor(4.0 * x), 5.0);
            float s2 = mod(floor(0.5 * x), 4.0);
            return 0.45 * s1 + 0.6 * s2 - 1.6;
        } else {
            return -2.4;
        }
    } else if (seg == 4) {
        // Formula 5: Dual waveform ring modulation
        return 1.8 * abs(saw(0.5 * x)) * tri(14.0 * x) + 0.6 * sin(0.8 * x) - 0.3;
    } else if (seg == 5) {
        // Formula 6: Percussive kick + resonant bell
        float m1 = fract(x);
        if (m1 < 0.45) {
            return 1.8 * sin(24.0 * PI * x) * exp(-4.0 * m1) + 0.4 * tri(6.0 * x);
        } else {
            return 0.6 + 1.6 * exp(-10.0 * (m1 - 0.45));
        }
    } else if (seg == 6) {
        // Formula 7: Glitch transient + sub-bass
        float fx = fract(x);
        float m4 = mod(x, 4.0);
        if (fx < 0.2) {
            return 1.5 * exp(-18.0 * fx) - 1.65;
        } else if (m4 < 2.5) {
            return -1.35 + 0.55 * exp(-10.0 * fract(4.0 * x));
        } else {
            float q1 = mod(floor(8.0 * x), 4.0);
            float q2 = mod(floor(2.0 * x), 2.0);
            return (1.0 + 3.0 * q1 + 5.0 * q2) / 12.0 + 0.22 * sin(36.0 * x);
        }
    } else if (seg == 7) {
        // Formula 8: Digital bytebeat arpeggiator
        float s4 = mod(floor(4.0 * x), 4.0);
        float s3 = mod(floor(4.0 * x), 3.0);
        if (s4 < 0.5) {
            return -1.5;
        } else if (s3 < 0.5) {
            float q = mod(floor(2.0 * x), 2.0);
            return (1.0 + 6.0 * q) / 12.0 + 1.0 * exp(-7.0 * fract(4.0 * x));
        } else {
            float q = mod(floor(4.0 * x), 2.0);
            return (-6.0 + 12.0 * q) / 12.0;
        }
    } else if (seg == 8) {
        // Formula 9: Harmonic additive synthesis
        float m4 = mod(x, 4.0);
        if (m4 < 0.45) {
            return 3.2 * exp(-12.0 * m4) - 1.75;
        } else if (m4 < 2.0) {
            return -0.75 + 1.15 * sin(6.0 * PI * x) + 0.22 * sin(30.0 * PI * x);
        } else if (m4 < 2.45) {
            return 2.2 * cos(38.0 * x) * exp(-2.5 * fract(x));
        } else {
            return -1.45 + 2.4 * abs(sin(12.0 * PI * x)) * (1.0 - 0.2 * mod(x, 2.0));
        }
    } else {
        // Formula 10: Piecewise Batman curve contour
        float ax = abs(x);
        if (ax <= 1.85) {
            return 2.25;
        } else if (ax <= 3.45) {
            return 2.25 - 0.84375 * (ax - 1.85);
        } else if (ax <= 7.0) {
            float under = max(0.0, 1.0 - (ax / 7.0) * (ax / 7.0));
            return 3.0 * sqrt(under);
        } else {
            return 0.0;
        }
    }
}

// Computes accumulated oscillator phase by integrating frequency along the curve up to segT.
// Fixed-grid numerical phase integration (50 steps across 5.0 seconds).
// Guarantees d(phase)/dt = 120.0 + normY * 380.0:
// Strictly climbs when Y climbs, and strictly descends when Y descends for x > 0.
float computePhase(int seg, float segT) {
    const int STEPS = 50;
    const float DT = SEG_DURATION / float(STEPS); // 0.10s per fixed bin
    int fullBins = int(floor(segT / DT));
    fullBins = clamp(fullBins, 0, STEPS - 1);

    float phase = 0.0;
    for (int k = 0; k < STEPS; k++) {
        if (k >= fullBins) break;
        float tk = (float(k) + 0.5) * DT;
        float prog = tk / SEG_DURATION;
        float x = mix(X_RANGE.x, X_RANGE.y, prog);
        float y = evalMathCurve(seg, x);
        float norm = clamp((y - Y_RANGE.x) / (Y_RANGE.y - Y_RANGE.x), 0.0, 1.0);
        phase += (120.0 + norm * 380.0) * DT;
    }

    // Remainder in current active bin
    float remT = segT - float(fullBins) * DT;
    if (remT > 0.0) {
        float tActive = float(fullBins) * DT + 0.5 * remT;
        float prog = tActive / SEG_DURATION;
        float x = mix(X_RANGE.x, X_RANGE.y, prog);
        float y = evalMathCurve(seg, x);
        float norm = clamp((y - Y_RANGE.x) / (Y_RANGE.y - Y_RANGE.x), 0.0, 1.0);
        phase += (120.0 + norm * 380.0) * remT;
    }

    return phase;
}

// Math Sounds - Visual Stage Pass

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Current cycle and segment (synchronized with mainSound)
    float t = mod(iTime, TOTAL_DURATION);
    int seg = SEG == -1 ?  int(floor(t / SEG_DURATION)) : SEG;
    float segT = mod(t, SEG_DURATION);
    float progress = segT / SEG_DURATION; // 0.0 .. 1.0

    // Canvas colors
    vec3 bgColor = vec3(0.08);
    vec3 darkOlive = vec3(1., 1., 0.0);
    vec3 tracerColor = vec3(0.9, 0.9, 0.0);

    // Fullscreen coordinate mapping using X_RANGE and Y_RANGE
    vec2 graphUV = fragCoord / iResolution.xy;
    float mathX = mix(X_RANGE.x, X_RANGE.y, graphUV.x);
    float mathY = mix(Y_RANGE.x, Y_RANGE.y, graphUV.y);

    vec3 col = bgColor;

    // 1. Coordinate Grid & Axes
    float gridX = abs(fract(mathX + 0.5) - 0.5);
    float gridY = abs(fract(mathY + 0.5) - 0.5);
    float gridLine = smoothstep(0.04, 0.0, min(gridX, gridY));
    col = mix(col, darkOlive, gridLine * 0.10);

    // Main X & Y Axes
    float axisX = smoothstep(0.04, 0.0, abs(mathY));
    float axisY = smoothstep(0.04, 0.0, abs(mathX));
    col = mix(col, darkOlive, max(axisX, axisY) * 0.35);

    // 2. Evaluated mathematical curve line
    float curveY = evalMathCurve(seg, mathX);
    float distCurve = abs(mathY - curveY);
    float pixelPitchY = (Y_RANGE.y - Y_RANGE.x) / iResolution.y;
    float curveLine = smoothstep(pixelPitchY * 2.5, 0.0, distCurve);
    col = mix(col, darkOlive, curveLine);

    // 3. Animated Tracer Dot moving along the curve in real-time
    float currentTracerX = mix(X_RANGE.x, X_RANGE.y, progress);
    float currentTracerY = evalMathCurve(seg, currentTracerX);
    vec2 tracerPos = vec2(
        mix(0.0, iResolution.x, (currentTracerX - X_RANGE.x) / (X_RANGE.y - X_RANGE.x)),
        mix(0.0, iResolution.y, (currentTracerY - Y_RANGE.x) / (Y_RANGE.y - Y_RANGE.x))
    );

    float distToTracer = length(fragCoord - tracerPos);
    float tracerDot = smoothstep(7.0, 4.0, distToTracer);
    float tracerGlow = 0.25 * smoothstep(22.0, 0.0, distToTracer);
    col = mix(col, tracerColor, tracerDot);
    col += vec3(0.9, 0.2, 0.2) * tracerGlow;

    fragColor = vec4(col, 1.0);
}

// Math Sounds - Sound Synthesis Pass
// Pitch strictly tracks curve height (Y) at the playhead position (X).
// Integrated phase guarantees d(phase)/dt = 120.0 + normY * 380.0.
// When Y climbs (x < 0), pitch climbs to apex; when Y descends (x > 0), pitch strictly descends back down.
// Every repetition is 100% identical and bit-for-bit repeatable.

vec2 mainSound(int samp, float time) {
    float t = mod(time, TOTAL_DURATION);
    int seg = SEG == -1 ?  int(floor(t / SEG_DURATION)) : SEG;
    float segT = mod(t, SEG_DURATION); // strictly 0.0 .. 5.0s
    float progress = segT / SEG_DURATION; // strictly 0.0 .. 1.0

    // Playhead x strictly mapped to graph domain [-8.5, 8.5]
    float currentX = mix(X_RANGE.x, X_RANGE.y, progress);
    // Math value evaluated directly from the curve y = f(x)
    float mathVal = evalMathCurve(seg, currentX);

    // Normalized height [0.0 .. 1.0] across Y_RANGE [-3.5, 3.5]
    float normY = clamp((mathVal - Y_RANGE.x) / (Y_RANGE.y - Y_RANGE.x), 0.0, 1.0);

    // Integrated phase guarantees instantaneous frequency strictly tracks curve height Y:
    // Lowest point on curve = 120 Hz, peak apex = 500 Hz.
    // As playhead passes x = 0 and Y decreases, pitch strictly descends back down!
    float phase = computePhase(seg, segT);

    float audioSignal = 0.0;

    if (seg == 0) {
        // Formula 1: Symmetrical Sawtooth wave tracked to curve height
        audioSignal = 0.40 * soundSaw(phase);
    } else if (seg == 1) {
        // Formula 2: Stepped quantized triangle wave strictly tracking step height Y
        audioSignal = 0.45 * soundTri(phase);
    } else if (seg == 2) {
        // Formula 3: Frequency Modulation (carrier modulated by sub-harmonic)
        audioSignal = 0.50 * soundFM(phase, fract(segT * 60.0), 2.5);
    } else if (seg == 3) {
        // Formula 4: Arpeggiated staircase note pulses (decaying envelopes)
        audioSignal = 0.50 * soundArp(phase, 4.0 * currentX, 7.0);
    } else if (seg == 4) {
        // Formula 5: Ring modulation (carrier x triangle modulator)
        audioSignal = 0.45 * soundSaw(fract(segT * 180.0)) * soundTri(phase);
    } else if (seg == 5) {
        // Formula 6: Percussive drum kick / transient burst
        audioSignal = 0.55 * soundDrum(phase, currentX, 6.0);
    } else if (seg == 6) {
        // Formula 7: Sub-bass + transient glitch click
        float glitch = (fract(currentX) < 0.15) ? 0.35 * soundSaw(fract(segT * 420.0)) : 0.0;
        audioSignal = 0.45 * soundSine(phase) + glitch;
    } else if (seg == 7) {
        // Formula 8: Digital 8-bit square wave
        audioSignal = 0.35 * soundSquare(phase) * normY;
    } else if (seg == 8) {
        // Formula 9: Rich additive harmonic tone (fundamental + 2nd + 3rd harmonics)
        audioSignal = 0.50 * soundHarmonics(phase);
    } else {
        // Formula 10: Smooth sine wave following Batman curve contour
        audioSignal = 0.50 * soundSine(phase);
    }

    // De-clicking micro-fade window at loop boundary (5ms attack/decay eliminates loop clicks)
    float loopFade = smoothstep(0.0, 0.006, segT) * (1.0 - smoothstep(4.994, 5.0, segT));
    audioSignal *= loopFade;

    // Symmetrical stereo widening
    float left = audioSignal;
    float right = audioSignal * 0.95 + 0.05 * soundSine(phase * 1.05);

    return clamp(vec2(left, right), -0.95, 0.95);
}
